window.amContent = function(slug){
  var r = (window.AM_CONTENTS||[]).filter(function(c){ return c.slug === slug; });
  return r.length ? r[0] : null;
};
/* 지금 보고 계신 자리에 맞는 글을 고릅니다.
   ⚠️ **억지로 붙이지 마세요.** 맞는 것이 없으면 빈 배열을 돌려주고
   화면은 구간째 뺍니다 (절대 규칙 2). 엉뚱한 데로 보내면 다음부터
   안 누릅니다.
   ⚠️ 분류가 같은 글이 **먼저**입니다. 원상복구 화면에 원상복구 글이
   아니라 사업자등록 글이 위에 오면 안 됩니다. */
window.amContentsFor = function(o){
  o = o || {};
  var all = window.AM_CONTENTS || [];
  /* 세 층으로 나눕니다 — 분류와 업종이 둘 다 맞는 글 → 하나만 맞는 글
     → 같은 쪽(창업/폐업)의 나머지.
     ⚠️ 업종 화면(`/startup/:industry`)은 **분류를 안 넘깁니다.** 업종만
     보고도 위로 올려야 합니다 — 그러지 않으면 카페 창업 화면 맨 앞에
     사업자등록 글이 앉고, 그건 엉뚱한 데로 보내는 것입니다. */
  var top = [], hit = [], rest = [];
  all.forEach(function(c){
    /* ⚠️ 업종이 붙은 글은 **그 업종 화면에서만** 냅니다. 업종을 안 고른
       화면에 카페 글이 뜨면 미용실 사장님을 엉뚱한 데로 보내는 것이고,
       그러면 다음부터 안 누릅니다. */
    if(o.industry && c.industry && c.industry !== o.industry) return;
    if(!o.industry && c.industry) return;
    var sideOk = !o.side || c.side === o.side || c.side === "both";
    var catOk  = !!(o.cat && c.cat === o.cat);
    /* ⚠️ 업종으로 올릴 때는 쪽도 봅니다. 안 보면 헬스장 **폐업** 글이
       헬스장 **창업** 화면 맨 앞에 앉습니다. */
    var indOk  = !!(o.industry && c.industry === o.industry && sideOk);
    if(catOk && indOk){ top.push(c); return; }
    if(catOk || indOk){ hit.push(c); return; }
    if(o.side && sideOk) rest.push(c);
  });
  return top.concat(hit, rest).slice(0, o.limit || 3);
};

window.amContents = function(f){
  f = f || {};
  return (window.AM_CONTENTS||[]).filter(function(c){
    if(f.side     && c.side !== f.side && c.side !== "both") return false;
    if(f.industry && c.industry && c.industry !== f.industry) return false;
    return true;
  });
};
